import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { newSession, openProject, type Session } from '../helpers';

// XeLaTeX and LuaLaTeX in WebAssembly: a real compilation of a tiny document with each engine, and an error case.
// The engine files are generated by scripts/fetch_xelatex_assets.py and fetch_lualatex_assets.py (not versioned): without them these tests are skipped.
const TEXLIVE = path.resolve(import.meta.dir, '../../../static/texlive');
const HAVE = (dir: string) => fs.existsSync(path.join(TEXLIVE, dir, 'emscripten'));

const DOC = '\\\\documentclass{article}\\\\begin{document}Hello from the engine test.\\\\end{document}';
const BAD = '\\\\documentclass{article}\\\\begin{document}\\\\undefinedcmd\\\\end{document}';

for (const [engine, dir, label] of [['wasm-xelatex', 'xelatex', 'XeLaTeX'], ['wasm-lualatex', 'lualatex', 'LuaLaTeX']] as const) {
  describe.skipIf(!HAVE(dir))(`${label} in the browser (WASM)`, () => {
    let s: Session;
    const result = () => s.page.evaluate(() => (window as any).__res);
    const compile = async (code: string) => {
      await s.page.evaluate(c => (globalThis as any).eval(`editor.setValue('${c}')`), code);
      await s.page.evaluate(() => { const w = window as any; if (!w.__hooked) { const o = w.renderCompileResult; w.renderCompileResult = (x: any) => { w.__res = x; return o(x); }; w.__hooked = true; } w.__res = null; });
      await s.page.click('#compile-btn');
      await s.page.waitForFunction(() => !!(window as any).__res, null, { timeout: 240000 });
      return result();
    };
    beforeAll(async () => {
      s = await newSession();
      await openProject(s.page);
      await s.page.waitForFunction(id => !!document.querySelector(`#engine-select option[value="${id}"]`), engine, { timeout: 30000 });
      await s.page.selectOption('#engine-select', engine);
    });
    afterAll(async () => { await s.context.close(); });

    test('compiles a small document and shows the PDF', async () => {
      const res = await compile(DOC);
      expect(res.success).toBe(true);
      await s.page.waitForSelector('#pdf-viewer canvas', { timeout: 60000 });
    }, 300000);

    test('a LaTeX error is reported in the diagnostics', async () => {
      const res = await compile(BAD);
      expect(res.success).toBe(false);
      await s.page.waitForFunction(() => /undefined/i.test(document.getElementById('diagnostics-list')?.textContent || ''), null, { timeout: 30000 });
    }, 300000);
  });
}
